param([string]$PublisherPath=(Join-Path $PSScriptRoot 'publisher.ps1'),[string]$PrivateComposeFixture='')
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest;[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
$publisher=[IO.File]::ReadAllText((Resolve-Path -LiteralPath $PublisherPath))
$tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseInput($publisher,[ref]$tokens,[ref]$errors);if($errors.Count){throw ($errors|Out-String)}
$functions=@($ast.EndBlock.Statements|Where-Object{$_-is[Management.Automation.Language.FunctionDefinitionAst]}|ForEach-Object{$_.Extent.Text})-join"`n"
. ([ScriptBlock]::Create($functions))
$script:SaveImpl=(Get-Command Save).ScriptBlock
function Save([string]$P,$V){if($script:FailReceipt-and($P-match'receipt(?:-[a-z-]+)?\.json$')){throw 'Injected receipt storage failure'};& $script:SaveImpl $P $V}
function D([string[]]$A){throw 'QA forbids all actual Docker calls'}
$qaRoot=Join-Path $env:TEMP ('codex-avito-publisher-qa-'+[guid]::NewGuid().ToString());$null=New-Item -ItemType Directory $qaRoot
$results=[Collections.ArrayList]::new()
function Require($Ok,[string]$Why){if(-not$Ok){throw $Why}}
function Setup([string]$Name){
 $script:Root=Join-Path $qaRoot (($results.Count+1).ToString('00')+'/root');$script:Backup=Join-Path $qaRoot (($results.Count+1).ToString('00')+'/private');$null=New-Item -ItemType Directory $Root -Force;$null=New-Item -ItemType Directory $Backup -Force
 $script:Release='synthetic-avito';$script:Tag='candidate-ref';$script:BaseReference='base-ref';$script:ExpectedBaseImage='base-image';$script:ExpectedCandidateImage='candidate-image';$script:JournalPath=Join-Path $Backup 'transition.json';$script:AtomicRoot=Join-Path $Backup 'atomic';$script:IoFault='';$script:FailReceipt=$false;$script:FailUpLostResponse=$false;$script:WebDrift=$false;$script:BindingDrift=$false;$script:UpCount=0;$script:ApiImage='base-image';$script:ApiCrashed=$false
 $a=[Text.Encoding]::UTF8.GetBytes("TEMICHEVVET_API_IMAGE=base-ref`r`nWEB_PIN=web-ref`r`nFAKE_SECRET=synthetic-only`r`n");[IO.File]::WriteAllBytes((Join-Path $Root '.env'),[byte[]](@(239,187,191)+@($a)))
 [IO.File]::WriteAllText((Join-Path $Root '.env.runtime'),"TEMICHEVVET_REMOTE_API_IMAGE=base-ref`nFAKE_SETTING=keep`n",[Text.UTF8Encoding]::new($false))
 [IO.File]::WriteAllText((Join-Path $Root 'docker-compose.yml'),'synthetic-compose',[Text.UTF8Encoding]::new($false))
 $cfg=@();foreach($name in @('.env','.env.runtime','docker-compose.yml')){Copy-Item (Join-Path $Root $name) (Join-Path $Backup $name);$cfg+=[pscustomobject]@{name=$name;sha256=FileSha (Join-Path $Root $name)}}
 $protected=@();foreach($name in @('clinic-crm-web','clinic-crm-postgres','clinic-crm-redis','clinic-crm-minio','clinic-crm-backup')){$protected+=[pscustomobject]@{name=$name;id=('id-'+$name);image=('image-'+$name);started='same-start'}}
 $runtime=[pscustomobject]@{dist=@();schemaSha256='schema';entrypointSha256='entrypoint';settingsVersion=6;settingsSha256='settings';mode='AUTO';rows=172;priceSha256='prices';clientVersion=@{client='same';engine='same'};successfulMigrations=@('same')}
 $script:State=[pscustomobject]@{release=$Release;sourceCommit='synthetic-source';baseImage=$ExpectedBaseImage;baseReference=$BaseReference;candidateImage=$ExpectedCandidateImage;candidateReference=$Tag;configuration=$cfg;protected=$protected;runtime=$runtime;manifest=@{files=@()};pinHashes=@()}
 $State.pinHashes=@(PinPlan);$before=[pscustomobject]@{services=[pscustomobject]@{api=[pscustomobject]@{image='base-ref';environment=[pscustomobject]@{SEED_ON_START='false'}};web=[pscustomobject]@{image='web-ref'}}};Save (Join-Path $Backup 'compose-private.json') $before;Journal 'PREPARED'
}
function C([string]$N){if($N-eq'clinic-crm-api'){return [pscustomobject]@{Image=$script:ApiImage;Id='api-id';State=@{Running=(-not$script:ApiCrashed);StartedAt='api-start'}}};$e=@($State.protected|Where-Object{$_.name-eq$N})[0];return [pscustomobject]@{Id=($e.id+$(if($script:WebDrift-and$N-eq'clinic-crm-web'){'-foreign'}else{''}));Image=$e.image;State=@{Running=$true;StartedAt=$e.started}}}
function I([string]$N){return [pscustomobject]@{Id=$(if($script:BindingDrift){'foreign-image'}elseif($N-eq$BaseReference){$ExpectedBaseImage}else{$ExpectedCandidateImage})}}
function Compose([switch]$Up){$text=[IO.File]::ReadAllText((Join-Path $Root '.env.runtime'));$new=$text.Contains('TEMICHEVVET_REMOTE_API_IMAGE='+$Tag);if($Up){$script:UpCount++;$script:ApiCrashed=$false;$script:ApiImage=if($new){$ExpectedCandidateImage}else{$ExpectedBaseImage};if($script:FailUpLostResponse){$script:FailUpLostResponse=$false;throw 'Injected lost Docker response'};return};$v=J (Join-Path $Backup 'compose-private.json');$v.services.api.image=if($new){$Tag}else{$BaseReference};return $v}
function RuntimeProbe{if($script:ApiCrashed){throw 'Synthetic crashed API cannot exec'};return $State.runtime}
function Healthy([string]$Image){Require (-not$script:ApiCrashed) 'Synthetic crashed API is unhealthy';Require ($script:ApiImage-eq$Image) 'Unexpected synthetic healthy image'}
function OriginalPins{foreach($f in $State.pinHashes){Require ((FileSha (Join-Path $Root $f.name))-eq$f.beforeSha256) ('Original bytes changed: '+$f.name)}}
function NewPins{foreach($f in $State.pinHashes){Require ((FileSha (Join-Path $Root $f.name))-eq$f.afterSha256) ('Candidate bytes changed: '+$f.name)}}
function Check([string]$Name,[ScriptBlock]$Body){Setup $Name;& $Body;$null=$results.Add(@{name=$Name;status='PASS'})}
try{
 Check 'replace-after-success-is-recognized' { $p=Join-Path $Backup 'atomic-check';[IO.File]::WriteAllText($p,'before');$script:IoFault='AfterReplace';Atomic $p ([Text.Encoding]::UTF8.GetBytes('after'));Require (([IO.File]::ReadAllText($p))-eq'after') 'Lost replace response did not preserve after bytes';$script:IoFault='';RecoverAtomic $p;Require (@(Get-ChildItem $AtomicRoot -File).Count-eq0) 'Stale atomic artifact remains' }
 Check 'replace-before-error-is-recoverable' { $p=Join-Path $Backup 'atomic-check';[IO.File]::WriteAllText($p,'before');$script:IoFault='BeforeReplace';$failed=$false;try{Atomic $p ([Text.Encoding]::UTF8.GetBytes('after'))}catch{$failed=$true};Require $failed 'Injected pre-replace failure missed';$script:IoFault='';RecoverAtomic $p;Require (([IO.File]::ReadAllText($p))-eq'before') 'Before bytes changed';Atomic $p ([Text.Encoding]::UTF8.GetBytes('after'));Require (([IO.File]::ReadAllText($p))-eq'after') 'Retry failed' }
 Check 'first-pin-failure-restores-exact-bom-and-newlines' { $script:IoFault='AfterPin1';$failed=$false;try{ApplyCandidate|Out-Null}catch{$failed=$true};$script:IoFault='';Require $failed 'Pin1 failure missed';OriginalPins;Require ($UpCount-eq0) 'Unnecessary API restart';Require ((Phase)-eq'ROLLED_BACK') 'Rollback not journalled' }
 Check 'second-pin-failure-restores-exact-bytes' { $script:IoFault='AfterPin2';$failed=$false;try{ApplyCandidate|Out-Null}catch{$failed=$true};$script:IoFault='';Require $failed 'Pin2 failure missed';OriginalPins;Require ($UpCount-eq0) 'Unnecessary API restart';Require ((Phase)-eq'ROLLED_BACK') 'Rollback not journalled' }
 Check 'receipt-failure-keeps-healthy-candidate-and-verify-finalizes' { $script:FailReceipt=$true;$failed=$false;try{ApplyCandidate|Out-Null}catch{$failed=$true};Require $failed 'Receipt failure missed';Require ($ApiImage-eq$ExpectedCandidateImage) 'Healthy candidate rolled back';Require ($UpCount-eq1) 'Unexpected restart after receipt failure';Require ((Phase)-eq'CANDIDATE_HEALTHY') 'Healthy checkpoint absent';NewPins;$script:FailReceipt=$false;FinalizeCandidate|Out-Null;Require ((Phase)-eq'APPLIED_VERIFIED') 'Verify did not finalize';Require ($UpCount-eq1) 'Verify repeated API up' }
 Check 'web-drift-blocks-recovery-before-config-or-up' { Journal 'APPLY_INTENT';SetApiPins;$script:WebDrift=$true;$failed=$false;try{RestoreKnownBase}catch{$failed=$true};Require $failed 'Web drift was accepted';NewPins;Require ($UpCount-eq0) 'API up during Web drift';Require ((Phase)-eq'APPLY_INTENT') 'Recovery journal changed before guard' }
 Check 'non-api-config-drift-is-preserved-without-recovery-up' { Journal 'APPLY_INTENT';SetApiPins;$p=Join-Path $Root '.env';[IO.File]::AppendAllText($p,'# external');$hash=FileSha $p;$failed=$false;try{RestoreKnownBase}catch{$failed=$true};Require $failed 'Non-API bytes drift was accepted';Require ((FileSha $p)-eq$hash) 'Foreign config was overwritten';Require ($UpCount-eq0) 'API up during config drift' }
 Check 'foreign-api-image-blocks-recovery-before-mutation' { Journal 'APPLY_INTENT';SetApiPins;$script:ApiImage='foreign-image';$failed=$false;try{RestoreKnownBase}catch{$failed=$true};Require $failed 'Foreign API image accepted';NewPins;Require ($UpCount-eq0) 'API up over foreign image' }
 Check 'base-tag-drift-blocks-recovery' { Journal 'APPLY_INTENT';SetApiPins;$script:BindingDrift=$true;$failed=$false;try{RestoreKnownBase}catch{$failed=$true};Require $failed 'Foreign base tag accepted';NewPins;Require ($UpCount-eq0) 'API up over changed base binding' }
 Check 'lost-up-response-and-repeated-verify-use-one-api-up' { $script:FailUpLostResponse=$true;ApplyCandidate|Out-Null;Require ($UpCount-eq1) 'Lost response repeated API up';Require ($ApiImage-eq$ExpectedCandidateImage) 'Lost response undid healthy candidate';FinalizeCandidate|Out-Null;Require ($UpCount-eq1) 'Verify repeated mutation';Require ((Phase)-eq'APPLIED_VERIFIED') 'Verified journal missing' }
 Check 'known-rollback-restores-only-reviewed-base' { ApplyCandidate|Out-Null;RestoreKnownBase;OriginalPins;Require ($ApiImage-eq$ExpectedBaseImage) 'Wrong rollback image';Require ($UpCount-eq2) 'Rollback sequence differs';Require ((Phase)-eq'ROLLED_BACK') 'Final rollback phase missing' }
 Check 'known-crashed-candidate-recovers-without-runtime-exec-dependency' { ApplyCandidate|Out-Null;$script:ApiCrashed=$true;RollbackCandidate|Out-Null;OriginalPins;Require ($ApiImage-eq$ExpectedBaseImage) 'Crashed candidate not rolled back';Require ($UpCount-eq2) 'Recovery restart sequence differs';Require ((Phase)-eq'ROLLED_BACK') 'Crashed recovery phase missing' }
 Check 'interrupted-pin-and-restore-phases-resume-idempotently' { foreach($phase in @('APPLY_INTENT','PINS_READY','ROLLBACK_INTENT','RESTORE_UP_INTENT')){Journal $phase;$script:IoFault='AfterPin1';try{SetApiPins}catch{};$script:IoFault='';RollbackCandidate|Out-Null;OriginalPins;Require ($UpCount-eq0) 'Baseline API unnecessarily restarted on resume';Require ((Phase)-eq'ROLLED_BACK') 'Resume rollback phase missing';RollbackCandidate|Out-Null;Require ($UpCount-eq0) 'Idempotent rollback repeated up'} }
 Check 'empty-objects-arrays-and-nulls-stay-distinct-under-strict-mode' { $shape=ConvertFrom-Json -InputObject '{"a":{},"b":[],"c":null,"d":[{},[],null],"e":{"ports":[],"options":{}}}';$clone=ConvertFrom-Json -InputObject ($shape|ConvertTo-Json -Depth 20);Require (Same $shape $clone) 'Empty JSON roundtrip differs';$clone.b=$null;Require (-not(Same $shape $clone)) 'Empty array collapsed to null';$clone=ConvertFrom-Json -InputObject ($shape|ConvertTo-Json -Depth 20);$clone.a=@();Require (-not(Same $shape $clone)) 'Empty object collapsed to array' }
 Check 'real-sealed-compose-roundtrip-is-read-only' { $real=if($PrivateComposeFixture){J $PrivateComposeFixture}else{ConvertFrom-Json -InputObject '{"services":{"api":{"image":"synthetic-api","ports":[],"labels":{},"healthcheck":null},"web":{"image":"synthetic-web","depends_on":{}}}}'};$clone=ConvertFrom-Json -InputObject ($real|ConvertTo-Json -Depth 65);Require (Same $real $clone) 'Real compose empty structures failed';$clone.services.api.image='synthetic-different-image';Require (-not(Same $real $clone)) 'Real compose image difference hidden' }
 Check 'canonical-order-and-unknown-phase-guards' { Require (Same @{a=1;b=@{z=2;y=3}} @{b=@{y=3;z=2};a=1}) 'Semantic property order differs';$failed=$false;try{AssertSnapshot $State @{} 'FOREIGN'}catch{$failed=$true};Require $failed 'Unknown phase accepted' }
 [pscustomobject]@{status='PASS';publisherSha256=(ByteSha ([Text.Encoding]::UTF8.GetBytes($publisher)));powershell=$PSVersionTable.PSVersion.ToString();caseCount=$results.Count;cases=$results;productionDockerCalls=0;productionConfigMutations=0}|ConvertTo-Json -Depth 8 -Compress
}finally{Remove-Item -LiteralPath $qaRoot -Recurse -Force}
